"""Moves over floors up and down by given instructions
    :param instructions: string of '(' (up) and ')' (down) characters
    :return: floor: number of floor where we stop
             basement_enter: number of first instruction where we entered negative values
    """
def move_over_floors(instructions: Any) -> object {
    floor = 0;
    i = 0;
    basement_enter = 0;
    for char in instructions {
        i += 1;
        if (char == '(') {
            floor += 1;
        } elif (char == ')') {
            floor -= 1;
        }
        if ((floor < 0) and (basement_enter == 0)) {
            basement_enter = i;
        }
    }
    return (floor, basement_enter);
}

"""
    Check how it is possible to construct the total route from the sub_routes (part a, b and c)

    Sub_routes has 3 items (0, 1, 2)

    """
def has_possible_route(total_route: Any, sub_routes: Any) -> object {
    state = `list();
    state.append((total_route, []));
    while (len(state) > 0) {
        (current_route, actions) = state.pop();
        if (len(current_route) == 0) {
            if (((len(actions) * 2) - 1) <= 20) {
                return (True, actions);
            } else {
                continue;
            }
        }
        for (idx, sub_route) in enumerate(sub_routes) {
            size = len(sub_route);
            if ((size > 0) and (current_route[:size] == sub_route)) {
                state.append((current_route[size:], (actions + [idx])));
            }
        }
    }
    return (False, None);
}

"""
    Gets the interactions of all characters with the main character
    :param links: List of all links in the network
    :param main_ch: The assumes main character name
    :return: Dictionary of all characters and their interactions with the main character
    """
def get_character_interactions(links: Any, main_ch: Any) -> object {
    character_interactions = {};
    for link in links {
        if (link['source'] == main_ch) {
            character_interactions[link['target']] = link['value'];
        } elif (link['target'] == main_ch) {
            if (link['source'] in character_interactions.keys()) {
                character_interactions[link['source']] += link['value'];
            } else {
                character_interactions[link['source']] = link['value'];
            }
        }
    }
    return character_interactions;
}

